import { handleApiRequest } from "./GlobalApiService";
const uiUrl=import.meta.env.VITE_UI

//Get Available banks in the databse
export const getBankDataForLogos=()=>{
    return handleApiRequest(
        "GET",
        `${uiUrl}/getBankDataForLogos`

    );
}

// Get the accounts for the selected bank
export const getAccountOfSelectedBank=(dto)=>{
    return handleApiRequest(
        "POST",
        `${uiUrl}/getAccountsToLink`,
        dto
    );
}

// Get the valid upiids generated by the bank and approved by the npci
export const getvalidUpis=(dto)=>{
    return handleApiRequest(
        "POST",
        `${uiUrl}/getValidUpis`,
        dto
    );
}
